insert into public.topics(id,name,discipline,version,content,published) values ('proportions','Razões e proporções','Matemática',1,'{"id":"proportions","name":"Razões e proporções","discipline":"Matemática","subtitle":"Pequenas relações. Grandes descobertas.","description":"Encontre o que conecta receitas, mapas e situações do seu dia.","relevance":"Proporções ajudam a entender escalas, misturas e gráficos. Elas abrem o caminho para regra de três.","prerequisiteIds":[],"priority":1,"version":1,"lessons":[{"id":"p1","kind":"concept","title":"Comparar é o primeiro passo","text":"Uma razão compara duas quantidades por uma divisão. Se uma receita usa 2 copos de suco e 6 de água, suco : água é 2 : 6. A ordem importa: água : suco é 6 : 2.","formula":"2 : 6 = 1 : 3"},{"id":"p2","kind":"example","title":"A receita cresceu. A relação ficou.","text":"Para dobrar a receita, multiplique os dois ingredientes por 2: 4 copos de suco e 12 de água. O sabor se mantém porque a razão continua 1 : 3.","formula":"2 / 6 = 4 / 12"},{"id":"p3","kind":"concept","title":"O tamanho muda; a escala permanece","text":"Na escala 1 : 1.000, cada centímetro do mapa representa 1.000 centímetros reais. Assim, 3 cm representam 3.000 cm, ou 30 metros. Compare quantidades na mesma unidade."},{"id":"p4","kind":"recall","title":"Agora, sem consultar","text":"Uma mistura tem 3 partes de tinta azul e 9 de branca. Qual é a razão azul : branca? E azul : mistura?","reveal":"Azul : branca = 3 : 9 = 1 : 3. Azul : mistura = 3 : 12 = 1 : 4. O segundo termo mudou!"}]}'::jsonb,true) on conflict(id) do update set name=excluded.name,discipline=excluded.discipline,version=excluded.version,content=excluded.content,published=true;
insert into public.questions(id,topic_id,purpose,difficulty,content) values ('proportions-0','proportions','diagnostic',1,'{"id":"proportions-0","topicId":"proportions","prompt":"Uma mistura usa 2 copos de concentrado e 6 de água. Qual é a razão concentrado : água?","options":["1 : 3","3 : 1","1 : 4","4 : 1"],"answer":0,"explanation":"Divida os dois termos por 2: 1 : 3. Concentrado : mistura seria 1 : 4. A ordem e as quantidades comparadas importam.","difficulty":1,"purpose":"diagnostic"}'::jsonb) on conflict(id) do update set purpose=excluded.purpose,difficulty=excluded.difficulty,content=excluded.content;
