insert into public.topics(id,name,discipline,version,content,published) values ('rule-of-three','Regra de três','Matemática',1,'{"id":"rule-of-three","name":"Regra de três","discipline":"Matemática","subtitle":"Você já conhece metade do caminho.","description":"Use relações conhecidas para descobrir o que falta.","relevance":"De preços a consumo e velocidade, regra de três transforma informações em uma relação simples.","prerequisiteIds":["proportions"],"priority":0.95,"version":1,"lessons":[{"id":"r1","kind":"concept","title":"Antes da conta, pense na relação","text":"Se a quantidade de cadernos dobra e cada um custa o mesmo, o custo dobra. São grandezas diretamente proporcionais. A regra de três exige uma relação proporcional."},{"id":"r2","kind":"example","title":"Um valor conhecido revela o outro","text":"3 cadernos custam R$ 24. Cada um custa R$ 8; então 5 custam R$ 40. A proporção confirma o raciocínio.","formula":"3 / 5 = 24 / x   →   x = 40"},{"id":"r3","kind":"concept","title":"Às vezes, mais significa menos","text":"Duas máquinas iguais levam 12 horas para um lote. Quatro máquinas, nas mesmas condições e sem interferência, levam 6 horas. Máquinas e tempo são inversamente proporcionais: o produto se mantém.","formula":"2 × 12 = 4 × 6"},{"id":"r4","kind":"recall","title":"Explique antes de calcular","text":"Com velocidade constante, dobrar o tempo dobra a distância? Para distância fixa, dobrar a velocidade faz o quê com o tempo?","reveal":"Distância e tempo são diretos com velocidade constante. Para distância fixa, dobrar a velocidade reduz o tempo à metade."}]}'::jsonb,true) on conflict(id) do update set name=excluded.name,discipline=excluded.discipline,version=excluded.version,content=excluded.content,published=true;
insert into public.questions(id,topic_id,purpose,difficulty,content) values ('rule-of-three-0','rule-of-three','diagnostic',1,'{"id":"rule-of-three-0","topicId":"rule-of-three","prompt":"2 cadernos custam R$ 16. Mantido o preço unitário, quanto custam 5 cadernos?","options":["R$ 40","R$ 19","R$ 20","R$ 16"],"answer":0,"explanation":"Cada caderno custa R$ 8. Quantidade e custo são diretos: 5 × 8 = 40.","difficulty":1,"purpose":"diagnostic"}'::jsonb) on conflict(id) do update set purpose=excluded.purpose,difficulty=excluded.difficulty,content=excluded.content;
insert into public.questions(id,topic_id,purpose,difficulty,content) values ('rule-of-three-1','rule-of-three','diagnostic',2,'{"id":"rule-of-three-1","topicId":"rule-of-three","prompt":"3 máquinas iguais fazem um lote em 12 horas. Com 6 máquinas, nas mesmas condições, quanto tempo leva?","options":["6 horas","12 horas","3 horas","24 horas"],"answer":0,"explanation":"O número de máquinas dobra e o tempo cai pela metade. São grandezas inversas: 12 ÷ 2 = 6 horas.","difficulty":2,"purpose":"diagnostic"}'::jsonb) on conflict(id) do update set purpose=excluded.purpose,difficulty=excluded.difficulty,content=excluded.content;
insert into public.questions(id,topic_id,purpose,difficulty,content) values ('rule-of-three-2','rule-of-three','diagnostic',3,'{"id":"rule-of-three-2","topicId":"rule-of-three","prompt":"Um carro percorre 240 km em 4 horas a velocidade constante. Quantos quilômetros percorre em 6 horas?","options":["360","180","242","240"],"answer":0,"explanation":"A velocidade é 60 km/h. Distância e tempo são diretos: 60 × 6 = 360 km.","difficulty":3,"purpose":"diagnostic"}'::jsonb) on conflict(id) do update set purpose=excluded.purpose,difficulty=excluded.difficulty,content=excluded.content;
