insert into public.topics(id,name,discipline,version,content,published) values ('cytology','Citologia','Biologia',1,'{"id":"cytology","name":"Citologia","discipline":"Biologia","subtitle":"Grandes estruturas, pequenas descobertas.","description":"Conheça a menor unidade capaz de realizar as funções da vida.","relevance":"Entender a célula ajuda a explicar nutrição, doenças e como a informação genética funciona.","prerequisiteIds":[],"priority":0.9,"version":1,"learningContext":{"overview":"Citologia estuda a célula: como sua membrana, seu material genético e suas estruturas trabalham juntas para manter a vida. Mais do que decorar nomes, vale compreender a função de cada estrutura e como a célula responde ao que acontece ao seu redor.","applications":["Em clínicas de fertilização, profissionais acompanham a fecundação e as primeiras divisões celulares de embriões com microscópios.","Na biotecnologia, células podem ser cultivadas em laboratório para pesquisar processos biológicos e produzir substâncias de interesse médico.","Na saúde, exames de células ajudam equipes especializadas a observar alterações em tecidos e orientar investigações clínicas."],"limitations":"Conhecer as estruturas celulares ajuda a interpretar esses contextos, mas não substitui técnicas laboratoriais, dados clínicos ou a avaliação de profissionais. Em cada situação, é preciso combinar citologia com outros conhecimentos."},"enemGuidance":{"status":"pending","priorities":[],"commonPatterns":[],"lowerIncidence":[],"examsAnalyzed":"","sources":[]},"lessons":[{"id":"c1","kind":"concept","title":"Uma pequena unidade, muitas funções","text":"Células possuem membrana, citoplasma, material genético e ribossomos. Procariontes, como bactérias, não têm núcleo delimitado. Eucariontes, como animais e plantas, têm núcleo e organelas membranosas."},{"id":"c2","kind":"example","title":"Pense em uma fábrica de proteínas","text":"Ribossomos produzem proteínas. O retículo rugoso participa da produção para exportação. O Golgi modifica e empacota. Mitocôndrias contribuem com energia em ATP. Lisossomos fazem digestão intracelular.","formula":"Ribossomo → retículo → Golgi → secreção"},{"id":"c3","kind":"concept","title":"A membrana regula as trocas","text":"Difusão acompanha o gradiente. Transporte ativo pode atuar contra ele, usando energia. Na osmose, a água atravessa membranas seletivas e tende ao meio de maior concentração efetiva de solutos."},{"id":"c4","kind":"recall","title":"Reconstrua com suas palavras","text":"O que uma bactéria tem em comum com uma célula animal? Qual possui núcleo delimitado?","reveal":"Ambas têm membrana, citoplasma, DNA e ribossomos. Só a célula animal tem núcleo delimitado; a bactéria possui nucleoide."}]}'::jsonb,true) on conflict(id) do update set name=excluded.name,discipline=excluded.discipline,version=excluded.version,content=excluded.content,published=true;
insert into public.questions(id,topic_id,purpose,difficulty,content) values ('cytology-0','cytology','diagnostic',1,'{"id":"cytology-0","topicId":"cytology","prompt":"Qual estrutura controla as trocas da célula com o meio?","options":["Ribossomo","Membrana plasmática","Cromossomo","Nucléolo"],"answer":1,"explanation":"A membrana plasmática possui permeabilidade seletiva.","difficulty":1,"purpose":"diagnostic"}'::jsonb) on conflict(id) do update set purpose=excluded.purpose,difficulty=excluded.difficulty,content=excluded.content;
insert into public.questions(id,topic_id,purpose,difficulty,content) values ('cytology-1','cytology','diagnostic',2,'{"id":"cytology-1","topicId":"cytology","prompt":"O que caracteriza uma célula procariótica?","options":["Não ter membrana","Não ter núcleo delimitado","Não produzir proteínas","Não ter DNA"],"answer":1,"explanation":"Procariontes possuem DNA, ribossomos e membrana, mas não núcleo delimitado por envoltório.","difficulty":2,"purpose":"diagnostic"}'::jsonb) on conflict(id) do update set purpose=excluded.purpose,difficulty=excluded.difficulty,content=excluded.content;
insert into public.questions(id,topic_id,purpose,difficulty,content) values ('cytology-2','cytology','diagnostic',3,'{"id":"cytology-2","topicId":"cytology","prompt":"Qual organela participa da respiração aeróbia em eucariontes?","options":["Golgi","Vacúolo","Mitocôndria","Lisossomo"],"answer":2,"explanation":"Mitocôndrias participam da produção de ATP pela respiração celular.","difficulty":3,"purpose":"diagnostic"}'::jsonb) on conflict(id) do update set purpose=excluded.purpose,difficulty=excluded.difficulty,content=excluded.content;
