insert into public.questions(id,topic_id,purpose,difficulty,content) values ('cytology-4','cytology','diagnostic',2,'{"id":"cytology-4","topicId":"cytology","prompt":"Uma célula animal em meio muito concentrado em solutos tende a:","options":["Ganhar água","Não trocar água","Perder água","Produzir cloroplastos"],"answer":2,"explanation":"Na osmose, a água tende ao meio com maior concentração efetiva de solutos.","difficulty":2,"purpose":"diagnostic"}'::jsonb) on conflict(id) do update set purpose=excluded.purpose,difficulty=excluded.difficulty,content=excluded.content;
insert into public.questions(id,topic_id,purpose,difficulty,content) values ('cytology-5','cytology','diagnostic',3,'{"id":"cytology-5","topicId":"cytology","prompt":"Qual estrutura existe em bactérias e células animais?","options":["Cloroplasto","Mitocôndria","Ribossomo","Núcleo delimitado"],"answer":2,"explanation":"Ambas possuem ribossomos. Bactérias não possuem organelas membranosas.","difficulty":3,"purpose":"diagnostic"}'::jsonb) on conflict(id) do update set purpose=excluded.purpose,difficulty=excluded.difficulty,content=excluded.content;
insert into public.questions(id,topic_id,purpose,difficulty,content) values ('cytology-6','cytology','practice',1,'{"id":"cytology-6","topicId":"cytology","prompt":"Uma célula secreta muitas proteínas. Qual estrutura deve ser abundante?","options":["Parede celular","Cloroplasto","Retículo endoplasmático rugoso","Centríolo"],"answer":2,"explanation":"O retículo rugoso possui ribossomos associados à produção de proteínas para secreção e membranas.","difficulty":1,"purpose":"practice"}'::jsonb) on conflict(id) do update set purpose=excluded.purpose,difficulty=excluded.difficulty,content=excluded.content;
insert into public.questions(id,topic_id,purpose,difficulty,content) values ('cytology-7','cytology','practice',2,'{"id":"cytology-7","topicId":"cytology","prompt":"Qual estrutura modifica e empacota proteínas para secreção?","options":["Centríolo","Mitocôndria","Complexo golgiense","Nucléolo"],"answer":2,"explanation":"O complexo golgiense processa e distribui substâncias em vesículas.","difficulty":2,"purpose":"practice"}'::jsonb) on conflict(id) do update set purpose=excluded.purpose,difficulty=excluded.difficulty,content=excluded.content;
insert into public.questions(id,topic_id,purpose,difficulty,content) values ('cytology-8','cytology','practice',3,'{"id":"cytology-8","topicId":"cytology","prompt":"Mover solutos contra o gradiente exige:","options":["Difusão simples","Osmose","Transporte ativo","Difusão facilitada"],"answer":2,"explanation":"Transporte ativo utiliza energia para mover substâncias contra o gradiente.","difficulty":3,"purpose":"practice"}'::jsonb) on conflict(id) do update set purpose=excluded.purpose,difficulty=excluded.difficulty,content=excluded.content;
insert into public.questions(id,topic_id,purpose,difficulty,content) values ('cytology-9','cytology','practice',1,'{"id":"cytology-9","topicId":"cytology","prompt":"Cloroplastos estão associados a qual processo?","options":["Respiração exclusiva","Produção bacteriana","Fotossíntese","Digestão"],"answer":2,"explanation":"Cloroplastos realizam fotossíntese em plantas e algas. Células vegetais também respiram.","difficulty":1,"purpose":"practice"}'::jsonb) on conflict(id) do update set purpose=excluded.purpose,difficulty=excluded.difficulty,content=excluded.content;
insert into public.questions(id,topic_id,purpose,difficulty,content) values ('cytology-10','cytology','practice',2,'{"id":"cytology-10","topicId":"cytology","prompt":"Qual é a função principal dos lisossomos?","options":["Guardar cromossomos","Produzir ribossomos","Digestão intracelular","Fotossíntese"],"answer":2,"explanation":"Lisossomos contêm enzimas que degradam materiais e componentes celulares.","difficulty":2,"purpose":"practice"}'::jsonb) on conflict(id) do update set purpose=excluded.purpose,difficulty=excluded.difficulty,content=excluded.content;
insert into public.questions(id,topic_id,purpose,difficulty,content) values ('cytology-11','cytology','practice',3,'{"id":"cytology-11","topicId":"cytology","prompt":"Uma célula vegetal em água fica túrgida porque:","options":["A membrana impede qualquer troca","Perde solutos","A água entra e a parede limita a expansão","O núcleo desaparece"],"answer":2,"explanation":"A água entra por osmose e a parede oferece resistência mecânica.","difficulty":3,"purpose":"practice"}'::jsonb) on conflict(id) do update set purpose=excluded.purpose,difficulty=excluded.difficulty,content=excluded.content;
insert into public.questions(id,topic_id,purpose,difficulty,content) values ('cytology-12','cytology','review',1,'{"id":"cytology-12","topicId":"cytology","prompt":"Uma toxina bloqueia ribossomos. Qual processo é diretamente afetado?","options":["Osmose","Síntese de proteínas","Difusão de oxigênio","Entrada de água"],"answer":1,"explanation":"Sem ribossomos funcionais, a tradução de RNA em proteínas é prejudicada.","difficulty":1,"purpose":"review"}'::jsonb) on conflict(id) do update set purpose=excluded.purpose,difficulty=excluded.difficulty,content=excluded.content;
insert into public.questions(id,topic_id,purpose,difficulty,content) values ('cytology-13','cytology','review',2,'{"id":"cytology-13","topicId":"cytology","prompt":"Por que um antibiótico dirigido à parede bacteriana pode agir seletivamente?","options":["Humanos não têm DNA","Bactérias não têm membrana","Humanos não têm ribossomos","Células humanas não têm parede celular"],"answer":3,"explanation":"Células humanas possuem membrana, mas não parede bacteriana.","difficulty":2,"purpose":"review"}'::jsonb) on conflict(id) do update set purpose=excluded.purpose,difficulty=excluded.difficulty,content=excluded.content;
