insert into public.questions(id,topic_id,purpose,difficulty,content) values ('cytology-17','cytology','review',3,'{"id":"cytology-17","topicId":"cytology","prompt":"Uma célula muscular demanda muito ATP. Qual organela contribui para isso?","options":["Mitocôndria","Golgi","Vacúolo","Lisossomo"],"answer":0,"explanation":"Mitocôndrias contribuem para a produção de ATP pela respiração celular.","difficulty":3,"purpose":"review"}'::jsonb) on conflict(id) do update set purpose=excluded.purpose,difficulty=excluded.difficulty,content=excluded.content;
insert into public.topics(id,name,discipline,version,content,published) values ('genetics','Fundamentos de genética','Biologia',1,'{"id":"genetics","name":"Fundamentos de genética","discipline":"Biologia","subtitle":"Tudo se conecta.","description":"Descubra como a informação passa de uma geração para outra.","relevance":"Genética conecta DNA, herança e diversidade. Probabilidade ajuda a interpretar os cruzamentos do ENEM.","prerequisiteIds":["cytology"],"priority":0.85,"version":1,"lessons":[{"id":"g1","kind":"concept","title":"DNA, genes e versões","text":"Um gene é uma região de DNA com informação funcional. Alelos são versões de um gene. Um indivíduo diploide pode ter alelos iguais (AA ou aa, homozigoto) ou diferentes (Aa, heterozigoto)."},{"id":"g2","kind":"concept","title":"O que você tem e o que se manifesta","text":"Genótipo é a constituição genética. Fenótipo reúne características observáveis, influenciadas por genes e ambiente. Em dominância completa, Aa expressa o fenótipo dominante. Dominante não significa mais comum ou melhor."},{"id":"g3","kind":"example","title":"Cada gameta leva um alelo","text":"Aa produz gametas A ou a. Em Aa × Aa, as combinações são AA, Aa, aA e aa. A chance de aa é 25% por descendente; isso não garante um aa a cada quatro nascimentos.","formula":"Aa × Aa → ¼ AA + ½ Aa + ¼ aa"},{"id":"g4","kind":"recall","title":"Faça o cruzamento de cabeça","text":"Quais gametas são produzidos por AA? E por aa? O que esperar de AA × aa?","reveal":"AA produz gametas A; aa produz gametas a. Todos os descendentes esperados são Aa."}]}'::jsonb,true) on conflict(id) do update set name=excluded.name,discipline=excluded.discipline,version=excluded.version,content=excluded.content,published=true;
insert into public.questions(id,topic_id,purpose,difficulty,content) values ('genetics-0','genetics','diagnostic',1,'{"id":"genetics-0","topicId":"genetics","prompt":"Um gene é, simplificadamente:","options":["Uma célula","Uma região do DNA com informação funcional","Uma organela","Um tecido"],"answer":1,"explanation":"Um gene é uma região do DNA com informação para um produto funcional, como RNA ou proteína.","difficulty":1,"purpose":"diagnostic"}'::jsonb) on conflict(id) do update set purpose=excluded.purpose,difficulty=excluded.difficulty,content=excluded.content;
insert into public.questions(id,topic_id,purpose,difficulty,content) values ('genetics-1','genetics','diagnostic',2,'{"id":"genetics-1","topicId":"genetics","prompt":"Alelos são:","options":["Organelas","Versões de um mesmo gene","Proteínas sempre iguais","Células idênticas"],"answer":1,"explanation":"Alelos são variantes de um gene em um mesmo locus.","difficulty":2,"purpose":"diagnostic"}'::jsonb) on conflict(id) do update set purpose=excluded.purpose,difficulty=excluded.difficulty,content=excluded.content;
insert into public.questions(id,topic_id,purpose,difficulty,content) values ('genetics-2','genetics','diagnostic',3,'{"id":"genetics-2","topicId":"genetics","prompt":"Qual genótipo é heterozigoto?","options":["aa","Todos","Aa","AA"],"answer":2,"explanation":"Aa tem dois alelos diferentes; AA e aa são homozigotos.","difficulty":3,"purpose":"diagnostic"}'::jsonb) on conflict(id) do update set purpose=excluded.purpose,difficulty=excluded.difficulty,content=excluded.content;
insert into public.questions(id,topic_id,purpose,difficulty,content) values ('genetics-3','genetics','diagnostic',1,'{"id":"genetics-3","topicId":"genetics","prompt":"Em Aa × aa, qual proporção esperada é aa?","options":["100%","0%","50%","75%"],"answer":2,"explanation":"Aa fornece A ou a. aa fornece apenas a. Metade das combinações é aa.","difficulty":1,"purpose":"diagnostic"}'::jsonb) on conflict(id) do update set purpose=excluded.purpose,difficulty=excluded.difficulty,content=excluded.content;
insert into public.questions(id,topic_id,purpose,difficulty,content) values ('genetics-4','genetics','diagnostic',2,'{"id":"genetics-4","topicId":"genetics","prompt":"Fenótipo se refere:","options":["Só à sequência do DNA","Apenas aos gametas","Às características observáveis","Só ao número de cromossomos"],"answer":2,"explanation":"Características observáveis resultam da interação entre genótipo e ambiente.","difficulty":2,"purpose":"diagnostic"}'::jsonb) on conflict(id) do update set purpose=excluded.purpose,difficulty=excluded.difficulty,content=excluded.content;
insert into public.questions(id,topic_id,purpose,difficulty,content) values ('genetics-5','genetics','diagnostic',3,'{"id":"genetics-5","topicId":"genetics","prompt":"Para esse gene, um indivíduo Aa forma gametas:","options":["Só AA","Só aa","A ou a","Todos Aa"],"answer":2,"explanation":"Os alelos segregam: cada gameta recebe um dos alelos.","difficulty":3,"purpose":"diagnostic"}'::jsonb) on conflict(id) do update set purpose=excluded.purpose,difficulty=excluded.difficulty,content=excluded.content;
insert into public.questions(id,topic_id,purpose,difficulty,content) values ('genetics-6','genetics','practice',1,'{"id":"genetics-6","topicId":"genetics","prompt":"Em Aa × Aa, qual a chance esperada de AA?","options":["75%","100%","25%","50%"],"answer":2,"explanation":"As combinações são AA, Aa, aA e aa; uma em quatro é AA.","difficulty":1,"purpose":"practice"}'::jsonb) on conflict(id) do update set purpose=excluded.purpose,difficulty=excluded.difficulty,content=excluded.content;
insert into public.questions(id,topic_id,purpose,difficulty,content) values ('genetics-7','genetics','practice',2,'{"id":"genetics-7","topicId":"genetics","prompt":"Um alelo dominante:","options":["Só existe em homens","É sempre mais comum","Manifesta seu efeito no heterozigoto em dominância completa","É sempre benéfico"],"answer":2,"explanation":"Dominância descreve expressão, não frequência nem vantagem.","difficulty":2,"purpose":"practice"}'::jsonb) on conflict(id) do update set purpose=excluded.purpose,difficulty=excluded.difficulty,content=excluded.content;
insert into public.questions(id,topic_id,purpose,difficulty,content) values ('genetics-8','genetics','practice',3,'{"id":"genetics-8","topicId":"genetics","prompt":"Em dominância completa, AA e Aa têm:","options":["Sempre fenótipos distintos","Mesmo genótipo","Mesmo fenótipo para a característica","Só alelos recessivos"],"answer":2,"explanation":"O fenótipo dominante se manifesta em ambos, embora os genótipos sejam diferentes.","difficulty":3,"purpose":"practice"}'::jsonb) on conflict(id) do update set purpose=excluded.purpose,difficulty=excluded.difficulty,content=excluded.content;
insert into public.questions(id,topic_id,purpose,difficulty,content) values ('genetics-9','genetics','practice',1,'{"id":"genetics-9","topicId":"genetics","prompt":"Em AA × aa, espera-se:","options":["Todos aa","Metade AA","Todos Aa","Todos AA"],"answer":2,"explanation":"Um genitor fornece A e o outro fornece a.","difficulty":1,"purpose":"practice"}'::jsonb) on conflict(id) do update set purpose=excluded.purpose,difficulty=excluded.difficulty,content=excluded.content;
insert into public.questions(id,topic_id,purpose,difficulty,content) values ('genetics-10','genetics','practice',2,'{"id":"genetics-10","topicId":"genetics","prompt":"A primeira lei de Mendel descreve:","options":["Genes criados por esforço","A união de núcleos em toda célula","A segregação dos alelos nos gametas","O desaparecimento de recessivos"],"answer":2,"explanation":"Os dois alelos se separam na formação dos gametas.","difficulty":2,"purpose":"practice"}'::jsonb) on conflict(id) do update set purpose=excluded.purpose,difficulty=excluded.difficulty,content=excluded.content;
insert into public.questions(id,topic_id,purpose,difficulty,content) values ('genetics-11','genetics','practice',3,'{"id":"genetics-11","topicId":"genetics","prompt":"Aa × Aa gera quatro descendentes. É garantido que um seja aa?","options":["Não, pois aa é impossível","Sim, sempre","Não: 25% é uma probabilidade por descendente","Sim, na mesma espécie"],"answer":2,"explanation":"Proporções são expectativas probabilísticas, não garantias em amostras pequenas.","difficulty":3,"purpose":"practice"}'::jsonb) on conflict(id) do update set purpose=excluded.purpose,difficulty=excluded.difficulty,content=excluded.content;
insert into public.questions(id,topic_id,purpose,difficulty,content) values ('genetics-12','genetics','review',1,'{"id":"genetics-12","topicId":"genetics","prompt":"Um cruzamento-teste com aa pode revelar:","options":["A idade do organismo","Se o genitor dominante é AA ou Aa","O número de organelas","O ambiente"],"answer":1,"explanation":"Um descendente recessivo revela que o genitor dominante fornece o alelo a.","difficulty":1,"purpose":"review"}'::jsonb) on conflict(id) do update set purpose=excluded.purpose,difficulty=excluded.difficulty,content=excluded.content;
insert into public.questions(id,topic_id,purpose,difficulty,content) values ('genetics-13','genetics','review',2,'{"id":"genetics-13","topicId":"genetics","prompt":"A proporção genotípica esperada de Aa × Aa é:","options":["3 AA : 1 aa","Todos Aa","1 AA : 1 aa","1 AA : 2 Aa : 1 aa"],"answer":3,"explanation":"AA, Aa, aA e aa: Aa e aA representam o mesmo genótipo.","difficulty":2,"purpose":"review"}'::jsonb) on conflict(id) do update set purpose=excluded.purpose,difficulty=excluded.difficulty,content=excluded.content;
insert into public.questions(id,topic_id,purpose,difficulty,content) values ('genetics-14','genetics','review',3,'{"id":"genetics-14","topicId":"genetics","prompt":"Uma característica muda com a alimentação. Isso mostra que:","options":["O ambiente pode influenciar o fenótipo","Alelos desaparecem","Genes nunca influenciam","O DNA sempre muda"],"answer":0,"explanation":"O ambiente afeta características sem necessariamente alterar a sequência do DNA.","difficulty":3,"purpose":"review"}'::jsonb) on conflict(id) do update set purpose=excluded.purpose,difficulty=excluded.difficulty,content=excluded.content;
insert into public.questions(id,topic_id,purpose,difficulty,content) values ('genetics-15','genetics','review',1,'{"id":"genetics-15","topicId":"genetics","prompt":"Em aa × aa, espera-se qual genótipo?","options":["aa","AA","Aa","AA ou aa"],"answer":0,"explanation":"Ambos os genitores fornecem apenas o alelo a.","difficulty":1,"purpose":"review"}'::jsonb) on conflict(id) do update set purpose=excluded.purpose,difficulty=excluded.difficulty,content=excluded.content;
insert into public.questions(id,topic_id,purpose,difficulty,content) values ('genetics-16','genetics','review',2,'{"id":"genetics-16","topicId":"genetics","prompt":"Dois alelos iguais caracterizam um indivíduo:","options":["Homozigoto","Heterozigoto","Sempre dominante","Sempre haploide"],"answer":0,"explanation":"Homozigose significa alelos iguais, como AA ou aa.","difficulty":2,"purpose":"review"}'::jsonb) on conflict(id) do update set purpose=excluded.purpose,difficulty=excluded.difficulty,content=excluded.content;
